import sys
from functools import reduce

def impossible():
	print('Impossible')

def main_proc():
	res = []
	cnt2resolve = 0
	n = int(input())
	target = [[[], []] for _ in range(8)]
	test = [0 for _ in range(8)]
	test[7] = 1
	src = [[] for _ in range(0, n + 1)]
	ct = ['1' for _ in range(0, n + 1)]
	input()
	for i in range(2, n + 1):
		ind = reduce(lambda a, b: (a << 1) + int(b), [int(_) for _ in input().split()])
		src[i].append(ind)
		target[ind][1].append(i)
	target[0][1] = []
	for x in target:
		if len(x[1]):
			cnt2resolve += 1
	input()
	for i in range(2, n + 1):
		ind = reduce(lambda a, b: (a << 1) + int(b), [int(_) for _ in input().split()])
		ind &= src[i][0]
		src[i].append(ind)
	for i in (7, 6, 5, 3, 4, 2, 1):
		if not target[i][0] and target[i][1]:
			for j in target[i][1]:
				if test[src[j][0]]:
					if not target[i][0]:
						target[i][0].append(test[src[j][0]])
						cnt2resolve -= 1
					test[src[j][1]] = j
	if cnt2resolve:
		for i in (6, 5, 3):
			if not target[i][0] and target[i][1]:
				tmp = 2
				for j in (4, 2, 1):
					if j & i:
						if test[j]:
							if src[test[j]][0] in (4, 2, 1):
								target[i][0].append(target[src[test[j]][0]][0][0])
							else:
								target[i][0].append(test[j])
							tmp -= 1
				if not tmp:
					cnt2resolve -= 1
	if not cnt2resolve:
		for i in range(7, 0, -1):
			for k in target[i][0]:
				if len(target[i][0]) == 2:
					tt = target[i][1][:1]
				else:
					tt = target[i][1]
				for j in tt:
					res.append(' '.join((str(k), str(j))))
			if len(target[i][0]) == 2 and len(target[i][1]) > 1:
				hp = target[i][1][0]
				ct[hp] = '0'
				for j in target[i][1][1:]:
					res.append(' '.join((str(hp), str(j))))
		print('Possible')
		print(' '.join(ct[1:]))
		print(len(res))
		print('\n'.join(res))
	else:
		print('Impossible')
	return
main_proc()
